import time

from providers.gateway import charge_failed


OPERATION = "payment.charge"
DEFAULT_MAX_ATTEMPTS = 3


def _default_send(amount, idempotency_key):
    return {"op": OPERATION, "key": idempotency_key}


def _pending_result(idempotency_key, attempts, last_failure):
    result = {
        "op": OPERATION,
        "key": idempotency_key,
        "status": "pending",
        "attempts": attempts,
        "retry_exhausted": True,
    }
    if isinstance(last_failure, BaseException):
        result["last_error"] = str(last_failure)
    else:
        result["last_failure"] = last_failure
    return result


def charge(
    amount,
    idempotency_key,
    *,
    send=None,
    max_attempts=DEFAULT_MAX_ATTEMPTS,
    retry_delay=0,
    sleep=time.sleep,
):
    """Submit a charge, retrying failed attempts under one idempotency key.

    Exhaustion is deliberately reported as pending: a timeout may happen after
    capture, so webhook settlement remains the authority for terminal status.
    """
    if not idempotency_key:
        raise ValueError("idempotency_key is required")
    if not isinstance(max_attempts, int) or isinstance(max_attempts, bool) or max_attempts < 1:
        raise ValueError("max_attempts must be a positive integer")
    if retry_delay < 0:
        raise ValueError("retry_delay must be non-negative")

    send = send or _default_send
    last_failure = None

    for attempt in range(1, max_attempts + 1):
        try:
            result = send(amount=amount, idempotency_key=idempotency_key)
        except Exception as error:
            last_failure = error
        else:
            if not charge_failed(result):
                return result
            last_failure = result

        if attempt < max_attempts and retry_delay:
            sleep(retry_delay)

    return _pending_result(idempotency_key, max_attempts, last_failure)
