FAILED_STATUSES = frozenset({"failed", "failure", "error", "timeout", "timed_out"})


def charge_failed(result):
    """Return whether a gateway result represents a failed attempt."""
    if not isinstance(result, dict):
        return False

    status = result.get("status")
    return result.get("success") is False or (
        isinstance(status, str) and status.lower() in FAILED_STATUSES
    )
