import unittest

from payments.charge import charge
from ui.status import render_status


class ChargeRetryTests(unittest.TestCase):
    def test_retries_failures_with_same_idempotency_key(self):
        calls = []

        def send(**request):
            calls.append(request)
            if len(calls) == 1:
                raise TimeoutError("captured, response lost")
            if len(calls) == 2:
                return {"status": "failed"}
            return {"status": "succeeded", "charge_id": "ch_123"}

        result = charge(1200, "order-123", send=send)

        self.assertEqual("succeeded", result["status"])
        self.assertEqual(
            [
                {"amount": 1200, "idempotency_key": "order-123"},
                {"amount": 1200, "idempotency_key": "order-123"},
                {"amount": 1200, "idempotency_key": "order-123"},
            ],
            calls,
        )

    def test_exhaustion_is_bounded_and_stays_pending(self):
        calls = []

        def send(**request):
            calls.append(request)
            raise TimeoutError("captured, response lost")

        result = charge(1200, "order-123", send=send, max_attempts=2)

        self.assertEqual(2, len(calls))
        self.assertEqual("pending", result["status"])
        self.assertEqual(2, result["attempts"])
        self.assertTrue(result["retry_exhausted"])

    def test_pre_webhook_status_is_pending(self):
        result = {"status": "failed"}

        self.assertEqual("pending", render_status(result))
        self.assertEqual("failed", render_status(result, webhook_settled=True))

    def test_existing_default_result_is_preserved(self):
        self.assertEqual(
            {"op": "payment.charge", "key": "order-123"},
            charge(1200, "order-123"),
        )


if __name__ == "__main__":
    unittest.main()

